@js:
java.toast('\n正在获取，请稍候😇');

var result = [];

url = getUrl();

function pushItem(title, sort, size) {
  result.push({
    "title": title,
    "url": (
      url
      + "/index.php?m=&c=mh&a=load_searchpage,"
      + JSON.stringify({
          "body": "page={{page}}&key=&sort%5B%5D=" + encodeURIComponent(sort) + "&paixu=&status=0&limitStatus=0",
          "method": "POST"
        })
    ),
    "style": {
      "layout_flexGrow": 1,
      "layout_flexBasisPercent": size
    }
  });
}

var bu = url + "/index.php?m=&c=mh&a=load_sort,";
var list = [];
try {
	var pages = source.getLoginInfoMap().get("设置发现页数（大于0）：");
} catch (e) { pages = "1"; };

for (var i = 1; i <= pages; i++) {
  var body = "page=" + i + "&limitStatus=0";
  var post = JSON.stringify({
    "body": body,
    "method": "POST"
  });

  var text = java.ajax(bu + post);
  var res;
  try {
    res = JSON.parse(text);
  } catch (e) {
    java.toast("解析失败，第 " + i + " 页: " + e);
    break;
  }

  // 安全判空 + 长度判断
  if (!res.info || res.info.length === 0) {
    break;
  }

  // 合并列表
  list = list.concat(res.info);
}

// 生成结果
for (var k = 0; k < list.length; k++) {
  var item = list[k];
  pushItem(item.name, item.name, null);
}

JSON.stringify(result);

