@js:
// 从基础URL提取ID
id = baseUrl.match(/\d+/)[0];

// 初始化变量
let allItems = [];
let page = 1;
const maxPage = 10; // 安全限制，防止无限循环
url = getUrl() + '/index.php?m=&c=book&a=getjino';

do {
    // 构建请求体（动态页码）
    body = `type=mh&id=${id}&p=${page}&sort=0`;

    // 发送POST请求
    res = java.post(url, body, {}).body();

    // 设置当前文档内容
    java.setContent(res, baseUrl);

    // 获取当前页的项目
    currentItems = java.getElements('.item>a').toArray();

    // 若当前页无内容则退出循环
    if (currentItems.length === 0) break;

    // 合并结果
    allItems = allItems.concat(currentItems);

    // 页数递增
    page++;
} while (page <= maxPage); // 双保险：页码限制+内容检查

// 最终结果赋值给list
list = allItems;

// 如需调试可取消注释
// java.log("总获取项目数：" + list.length);

